// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {ReentrancyGuardTransient} from "lib/solady/src/utils/ReentrancyGuardTransient.sol";
import {SafeTransferLib} from "lib/solady/src/utils/SafeTransferLib.sol";
import {FacilityRoles} from "./FacilityRoles.sol";

import {IFacilityPositionManager} from "src/interfaces/facility/base/IFacilityPositionManager.sol";
import {IPositionManager} from "src/interfaces/manager/IPositionManager.sol";
import {WithdrawalStrategy} from "src/interfaces/manager/base/IPositionManagerAdmin.sol";
import {LibIntent, Intent, Asset, BalanceSnapshot} from "src/libs/facility/LibIntent.sol";
import {LibStorage, FacilityStorageData} from "src/libs/facility/LibStorage.sol";
import {LibFacilityErrors} from "src/libs/facility/LibFacilityErrors.sol";

/// @title FacilityPositionManager
/// @author 3F Protocol
/// @notice Abstract contract implementing position manager operations for intents.
/// @dev Allows depositing into, withdrawing from, and burning shares of position managers.
abstract contract FacilityPositionManager is IFacilityPositionManager, ReentrancyGuardTransient, FacilityRoles {
  using SafeTransferLib for address;
  using LibStorage for FacilityStorageData;
  using LibIntent for Intent;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                 POSITION MANAGER OPERATIONS                */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityPositionManager
  /// @dev Deposits collateral into the position manager and borrows debt.
  ///      The intent must be in resolving state and have enough collateral to deposit.
  function depositManager(uint256 id, uint256 depositAmount, uint256 borrowAmount, bool useTarget)
    external
    override
    nonReentrant
    onlyRoles(FACILITATOR_ROLE)
  {
    // getting the initial parameters
    (
      Intent storage _intent,
      address _positionManager,
      address _collateralAsset,
      address _debtAsset,
      BalanceSnapshot memory collateralSnapshot,
      BalanceSnapshot memory debtSnapshot,
      BalanceSnapshot memory sharesSnapshot
    ) = _initialPmParameters(id, useTarget);

    if (depositAmount > 0) {
      // if we have non null collateral, approve the position manager to pull it
      _collateralAsset.safeApproveWithRetry(_positionManager, depositAmount);
    }

    // deposit the collateral and borrow the debt
    IPositionManager(_positionManager).deposit(depositAmount, borrowAmount);

    if (depositAmount > 0) {
      // reset approval to 0
      _collateralAsset.safeApproveWithRetry(_positionManager, 0);
    }

    // commit snapshots to record the balance changes
    _commitSnapshots(_intent, id, collateralSnapshot, debtSnapshot, sharesSnapshot, _positionManager);
  }

  /// @inheritdoc IFacilityPositionManager
  /// @dev Withdraws collateral from the position manager and repays debt.
  ///      The intent must be in resolving state and have enough debt to repay.
  function withdrawManager(
    uint256 id,
    uint256 withdrawAmount,
    uint256 repayAmount,
    bool useTarget,
    WithdrawalStrategy strategy
  ) external override nonReentrant onlyRoles(FACILITATOR_ROLE) {
    // getting the initial parameters
    (
      Intent storage _intent,
      address _positionManager,
      address _collateralAsset,
      address _debtAsset,
      BalanceSnapshot memory collateralSnapshot,
      BalanceSnapshot memory debtSnapshot,
      BalanceSnapshot memory sharesSnapshot
    ) = _initialPmParameters(id, useTarget);

    if (repayAmount > 0) {
      // if we have non null debt, approve the position manager to pull it
      _debtAsset.safeApproveWithRetry(_positionManager, repayAmount);
    }

    // repay the debt and withdraw the collateral
    IPositionManager(_positionManager).withdraw(withdrawAmount, repayAmount, strategy);

    if (repayAmount > 0) {
      // reset approval to 0
      _debtAsset.safeApproveWithRetry(_positionManager, 0);
    }

    // commit snapshots to record the balance changes
    _commitSnapshots(_intent, id, collateralSnapshot, debtSnapshot, sharesSnapshot, _positionManager);
  }

  /// @inheritdoc IFacilityPositionManager
  /// @dev Burns position manager shares by sending debt to the position manager and receiving collateral back.
  ///      The intent must be in resolving state and have enough debt to repay.
  function burnManager(uint256 id, uint256 shares, bool useTarget, WithdrawalStrategy strategy)
    external
    override
    nonReentrant
    onlyRoles(FACILITATOR_ROLE)
  {
    // getting the initial parameters
    (
      Intent storage _intent,
      address _positionManager,
      address _collateralAsset,
      address _debtAsset,
      BalanceSnapshot memory collateralSnapshot,
      BalanceSnapshot memory debtSnapshot,
      BalanceSnapshot memory sharesSnapshot
    ) = _initialPmParameters(id, useTarget);

    // give infinite approval of the debt asset to the position manager
    _debtAsset.safeApproveWithRetry(_positionManager, type(uint256).max);

    // burn the shares by sending debt to the position manager and receiving collateral back
    IPositionManager(_positionManager).burn(shares, strategy);

    // commit snapshots to record the balance changes
    _commitSnapshots(_intent, id, collateralSnapshot, debtSnapshot, sharesSnapshot, _positionManager);

    // reset approval of the debt asset to the position manager to 0
    _debtAsset.safeApproveWithRetry(_positionManager, 0);
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                   INTERNALS OPERATIONS                     */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Gets the initial parameters related to a position manager for a given intent.
  /// @dev Retrieves the resolving intent and reads either the targetAsset or depositAsset as the selected asset,
  ///      checks if it is a position manager, then fetches the related collateral and debt assets from the manager.
  ///      Reverts with `InvalidPositionManagerAssets()` if collateralAsset, debtAsset, or positionManager overlap,
  ///      preventing snapshot-based double-counting attacks (CS-GRUNT-062).
  /// @param id The intent id.
  /// @param useTarget If true, use the targetAsset; otherwise, use the depositAsset.
  /// @return _intent Storage pointer to the retrieved intent struct.
  /// @return positionManager Address of the position manager contract.
  /// @return collateralAsset Address of the collateral asset handled by the position manager.
  /// @return debtAsset Address of the debt asset handled by the position manager.
  /// @return collateralSnapshot Snapshot of the collateral asset balance before the operation.
  /// @return debtSnapshot Snapshot of the debt asset balance before the operation.
  /// @return sharesSnapshot Snapshot of the shares balance before the operation.
  function _initialPmParameters(uint256 id, bool useTarget)
    private
    view
    returns (
      Intent storage _intent,
      address positionManager,
      address collateralAsset,
      address debtAsset,
      BalanceSnapshot memory collateralSnapshot,
      BalanceSnapshot memory debtSnapshot,
      BalanceSnapshot memory sharesSnapshot
    )
  {
    // check if the facility is paused
    LibStorage.checkNotPaused();
    // getting the resolving intent
    _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // getting the selected asset (simple ternary since we read from storage)
    Asset storage _selected = useTarget ? _intent.properties.targetAsset : _intent.properties.depositAsset;
    // ensure the selected asset is a position manager
    if (!_selected.isPositionManager) revert LibFacilityErrors.AssetNotPositionManager(_selected.asset);

    // get the position manager address
    positionManager = _selected.asset;
    // get the position manager assets
    (collateralAsset, debtAsset) = IPositionManager(positionManager).assets();

    // if (collateralAsset == debtAsset || collateralAsset == positionManager || debtAsset == positionManager)
    //   revert LibFacilityErrors.InvalidPositionManagerAssets();
    assembly ("memory-safe") {
      if or(eq(collateralAsset, debtAsset), or(eq(collateralAsset, positionManager), eq(debtAsset, positionManager))) {
        mstore(0, 0x62e437a4) // LibFacilityErrors.InvalidPositionManagerAssets()
        revert(0x1c, 0x04)
      }
    }

    // take snapshots before the operation
    collateralSnapshot = LibIntent.takeBalanceSnapshot(collateralAsset);
    debtSnapshot = LibIntent.takeBalanceSnapshot(debtAsset);
    sharesSnapshot = LibIntent.takeBalanceSnapshot(positionManager);
  }

  /// @notice Commits all balance snapshots after a position manager operation.
  /// @dev Records balance changes for collateral, debt, and shares by comparing
  ///      pre-operation snapshots with current balances.
  /// @param _intent Storage pointer to the intent struct.
  /// @param id The intent id.
  /// @param collateralSnapshot Snapshot of the collateral asset balance before the operation.
  /// @param debtSnapshot Snapshot of the debt asset balance before the operation.
  /// @param sharesSnapshot Snapshot of the shares balance before the operation.
  /// @param positionManager Address of the position manager (counterparty for collateral/debt events).
  function _commitSnapshots(
    Intent storage _intent,
    uint256 id,
    BalanceSnapshot memory collateralSnapshot,
    BalanceSnapshot memory debtSnapshot,
    BalanceSnapshot memory sharesSnapshot,
    address positionManager
  ) private {
    _intent.commitBalanceSnapshot(id, collateralSnapshot, positionManager);
    _intent.commitBalanceSnapshot(id, debtSnapshot, positionManager);
    _intent.commitBalanceSnapshot(id, sharesSnapshot, address(0));
  }
}

lib/grunt/src/facility/base/FacilityFund.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {ReentrancyGuardTransient} from "lib/solady/src/utils/ReentrancyGuardTransient.sol";
import {FacilityRoles} from "./FacilityRoles.sol";
import {SafeTransferLib} from "lib/solady/src/utils/SafeTransferLib.sol";
import {IFacilityFunds} from "src/interfaces/facility/base/IFacilityFunds.sol";
import {IFund} from "src/interfaces/funds/IFund.sol";
import {LibIntent, Intent, BalanceSnapshot} from "src/libs/facility/LibIntent.sol";
import {LibStorage, FacilityStorageData} from "src/libs/facility/LibStorage.sol";
import {LibFacilityErrors} from "src/libs/facility/LibFacilityErrors.sol";
import {Order, Mode, State, LibOrder} from "src/libs/funds/Order.sol";

/// @title FacilityFunds
/// @author 3F Protocol
/// @notice Abstract contract implementing fund operations for intents.
/// @dev Allows creating, canceling, committing, unlocking, and recovering fund orders.
abstract contract FacilityFunds is IFacilityFunds, ReentrancyGuardTransient, FacilityRoles {
  using LibStorage for FacilityStorageData;
  using LibIntent for Intent;
  using SafeTransferLib for address;
  using LibOrder for Order;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           VIEWS                            */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityFunds
  function getOrder(uint256 id) external view override returns (Order memory order, bytes32 orderId) {
    Intent storage _intent = LibStorage.facilityStorage().getIntent(id);
    order = _intent.order;
    orderId = order.toId(_intent.fund);
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                        FUND OPERATIONS                     */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityFunds
  /// @dev Creates a fund order for the intent. The intent must be in resolving state
  ///      and must not have an active order. The order is stored in the intent for later operations.
  function create(uint256 id, uint256 amount, uint256 minAmountOut, Mode mode)
    external
    override
    onlyRoles(FACILITATOR_ROLE)
    nonReentrant
    returns (Order memory order)
  {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // checks that the intent has a fund
    address _fund = _intent.fund;
    if (_fund == address(0)) revert LibFacilityErrors.MissingFund(id);

    // ensure the intent has no pending order
    _intent.checkNoPendingOrder(id);

    // create order with a block/id unique salt
    order = Order({
      mode: mode,
      owner: address(this),
      receiver: address(this),
      input: amount,
      output: minAmountOut,
      salt: keccak256(abi.encode(address(this), block.timestamp, id))
    });
    emit CreatingOrder(id, order.toId(_fund));
    IFund(_fund).create(order);

    // update order in intent
    _intent.order = order;
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Cancels the current fund order for the intent.
  ///      The intent must have an active order.
  function cancel(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    // cancel order with the fund and delete it from the intent
    IFund(_intent.fund).cancel(_intent.order);
    _intent.removeOrderAndFund(id);
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Commits the current fund order for the intent.
  ///      Transfers the input tokens to the fund and calls commit on it.
  ///      The intent must have an active order.
  function commit(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    // get the order and token to deposit
    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    address _tokenIn = _order.mode == Mode.DEPOSIT ? IFund(_fund).asset() : IFund(_fund).share();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenIn);

    // commit the funds
    _tokenIn.safeApproveWithRetry(_fund, _order.input);
    (, uint256 _committedAmount) = IFund(_fund).commit(_order);
    if (_committedAmount != _order.input) {
      revert LibFacilityErrors.CommitAmountMismatch(id, _order.input, _committedAmount);
    }
    // reset approval to 0
    _tokenIn.safeApproveWithRetry(_fund, 0);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Unlocks the current fund order for the intent.
  ///      Receives the output tokens from the fund after successful processing.
  ///      Deletes the order if the state reaches ENDED.
  function unlock(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    // If this is the deposit, an unlock gives shares, otherwise it gives assets
    address _tokenOut = _order.mode == Mode.DEPOSIT ? IFund(_fund).share() : IFund(_fund).asset();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenOut);

    // unlock the funds
    (State _state,) = IFund(_fund).unlock(_order);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);

    if (_state == State.ENDED) {
      // if the order is ended, delete the order
      _intent.removeOrderAndFund(id);
    }
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Recovers assets from the current fund order for the intent after failed processing.
  ///      Receives the input tokens back from the fund.
  ///      Deletes the order if the state reaches ENDED.
  function recover(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    // If this is the deposit, a recover gives assets back, otherwise it gives shares back
    address _tokenIn = _order.mode == Mode.DEPOSIT ? IFund(_fund).asset() : IFund(_fund).share();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenIn);

    // recover the funds
    (State _state,) = IFund(_fund).recover(_order);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);

    if (_state == State.ENDED) {
      // if the order is ended, delete the order
      _intent.removeOrderAndFund(id);
    }
  }
}

lib/grunt/src/facility/base/FacilityInte.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {FacilityRoles} from "./FacilityRoles.sol";
import {EIP712} from "lib/solady/src/utils/EIP712.sol";
import {IFacilityIntents} from "src/interfaces/facility/base/IFacilityIntents.sol";
import {IFund} from "src/interfaces/funds/IFund.sol";
import {IPositionManager} from "src/interfaces/manager/IPositionManager.sol";
import {IRequestInteractions} from "src/interfaces/request/IRequestInteractions.sol";
import {LibIntent, Intent, IntentProperties, Asset} from "src/libs/facility/LibIntent.sol";
import {LibStorage, FacilityStorageData} from "src/libs/facility/LibStorage.sol";
import {LibFacilityErrors} from "src/libs/facility/LibFacilityErrors.sol";
import {LibAddress} from "src/libs/facility/LibAddress.sol";
import {LibChecks} from "src/libs/common/LibChecks.sol";

/// @title FacilityIntents
/// @author 3F Protocol
/// @notice Abstract contract implementing intent management operations.
/// @dev Allows creating intents and updating their configuration.
abstract contract FacilityIntents is IFacilityIntents, EIP712, FacilityRoles {
  using LibStorage for FacilityStorageData;
  using LibIntent for Intent;
  using LibChecks for address;
  using LibAddress for address;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                         CONSTANTS                          */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice EIP-712 typehash for setFund params.
  /// @dev keccak256("SetFundParams(uint256 id,address newFund,uint256 deadline)")
  bytes32 internal constant SET_FUND_PARAMS_TYPEHASH =
    0x5b29fe7a3c7ef719629449a6e2c108e8c6d692027b5327c7edbdc163a7ce1b0b;

  /// @notice EIP-712 typehash for setRequest params.
  /// @dev keccak256("SetRequestParams(uint256 id,address newRequest,uint256 deadline)")
  bytes32 internal constant SET_REQUEST_PARAMS_TYPEHASH =
    0x3fab97cdfeba7b67ca42aeebb63ab14ea67e6637d1e42acb3a06b721f7d72438;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           VIEWS                            */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityIntents
  function getIntent(uint256 id)
    external
    view
    override
    returns (IntentProperties memory properties, address fund, address request, bool resolved)
  {
    Intent storage _intent = LibStorage.facilityStorage().getIntent(id);
    properties = _intent.properties;
    fund = _intent.fund;
    request = _intent.request;
    resolved = _intent.resolved;
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                     INTENT MANAGEMENT                      */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityIntents
  /// @dev Creates a new intent with the given properties. The resolve start must be in the future.
  ///      At least one of deposit or target asset must be a position manager.
  function createIntent(IntentProperties calldata params)
    external
    override
    onlyOwnerOrRoles(FACILITATOR_ROLE)
    returns (uint256 id)
  {
    LibStorage.checkNotPaused();
    if (params.resolveStart <= block.timestamp) {
      revert LibFacilityErrors.InvalidResolveStart(params.resolveStart, uint40(block.timestamp));
    }

    FacilityStorageData storage _facilityStorage = LibStorage.facilityStorage();
    Intent storage _intent;
    (_intent, id) = _facilityStorage.createIntent(params.depositAsset, params.quorum, params.transferableIntent);

    _intent.updateTargetAsset(id, params.targetAsset, params.guardKey);
    _intent.updateDepositCap(id, params.depositCap);
    _intent.updateResolveStart(id, params.resolveStart);
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Updates the target asset and guard key for an intent.
  ///      The new configuration must be compatible with the deposit asset.
  function updateTarget(uint256 id, Asset calldata newTargetAsset, address newGuardKey) external override onlyOwner {
    LibStorage.checkNotPaused();
    LibStorage.facilityStorage().getIntent(id).updateTargetAsset(id, newTargetAsset, newGuardKey);
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Locks the intent by setting resolve start to current timestamp.
  ///      The intent must not already be resolving or resolved.
  function lock(uint256 id) external override onlyRoles(FACILITATOR_ROLE) {
    LibStorage.checkNotPaused();
    LibStorage.facilityStorage().getDepositingIntent(id).updateResolveStart(id, uint40(block.timestamp));
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Resolves the intent, enabling claims for users.
  ///      The intent must be in resolving state with no active order.
  ///      If a request is set, it must be repaid.
  function resolve(uint256 id) external override onlyRoles(FACILITATOR_ROLE) {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // checks that the request is repaid
    _intent.checkRequestRepaid();

    // sync stale ended orders
    _intent.syncEndedOrder(id);

    // checks that the intent has no pending order
    _intent.checkNoPendingOrder(id);

    // update the intent's resolved state
    _intent.resolved = true;
    emit IntentResolved(id);
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Sets a new deposit cap for the intent.
  ///      The intent must be in the depositing state.
  function setDepositCap(uint256 id, uint256 newDepositCap) external override onlyRoles(FACILITATOR_ROLE) {
    LibStorage.checkNotPaused();
    LibStorage.facilityStorage().getDepositingIntent(id).updateDepositCap(id, newDepositCap);
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Sets a new fund address for the intent.
  ///      The fund's asset and share must match the position manager's assets.
  ///      The intent must not have an active order.
  ///      If the fund is address(0), the fund is removed from the intent.
  function setFund(
    uint256 id,
    address newFund,
    uint256 deadline,
    address[] calldata signers,
    bytes[] calldata signatures
  ) external override onlyRoles(FACILITATOR_ROLE) {
    LibStorage.checkNotPaused();
    FacilityStorageData storage _facilityStorage = LibStorage.facilityStorage();
    Intent storage _intent = _facilityStorage.getIntent(id);

    // sync stale ended orders
    _intent.syncEndedOrder(id);

    // skip if the fund is already set to the same address
    if (_intent.fund == newFund) return;

    // ensure the intent has no pending order
    _intent.checkNoPendingOrder(id);

    if (newFund == address(0)) {
      // if the fund is address(0), remove the fund (no signature required)
      _intent.removeOrderAndFund(id);
      return;
    }

    if (block.timestamp > deadline) revert LibFacilityErrors.DeadlineExpired();

    _checkSignatures(
      _facilityStorage,
      _hashTypedData(keccak256(abi.encode(SET_FUND_PARAMS_TYPEHASH, id, newFund, deadline))),
      signers,
      signatures,
      _intent.properties.quorum
    );

    // ensure the fund is not already in use
    _facilityStorage.checkFundIntent(newFund, id);

    // ensure the fund is a contract
    newFund.checkContract();

    // ensure the fund's assets match the position manager's assets
    (address _pmCollateral, address _pmDebt) = IPositionManager(_intent.properties.guardKey).assets();
    IFund(newFund).asset().checkAssetsMatch(_pmDebt);
    IFund(newFund).share().checkAssetsMatch(_pmCollateral);

    // abandon the old fund if it exists
    _facilityStorage.abandonFund(_intent.fund);

    // update the intent's fund
    _intent.fund = newFund;
    emit FundUpdated(id, newFund);
  }

  /// @inheritdoc IFacilityIntents
  /// @dev Sets a new request address for the intent.
  ///      The request's asset must match the position manager's debt asset.
  ///      If a previous request exists, it must be repaid.
  ///      If the request is address(0), the request is removed from the intent.
  function setRequest(
    uint256 id,
    address newRequest,
    uint256 deadline,
    address[] calldata signers,
    bytes[] calldata signatures
  ) external override onlyRoles(FACILITATOR_ROLE) {
    LibStorage.checkNotPaused();
    FacilityStorageData storage _facilityStorage = LibStorage.facilityStorage();
    Intent storage _intent = _facilityStorage.getIntent(id);

    // skip if the request is already set to the same address
    if (_intent.request == newRequest) return;

    // ensure that there is no unpaid request bound to the intent
    _intent.checkRequestRepaid();

    if (newRequest != address(0)) {
      if (block.timestamp > deadline) revert LibFacilityErrors.DeadlineExpired();

      _checkSignatures(
        _facilityStorage,
        _hashTypedData(keccak256(abi.encode(SET_REQUEST_PARAMS_TYPEHASH, id, newRequest, deadline))),
        signers,
        signatures,
        _intent.properties.quorum
      );

      // ensure the request is a contract
      newRequest.checkContract();

      // ensure the request is not already in use
      _facilityStorage.checkRequestIntent(newRequest, id);

      // ensure the request's asset matches the position manager's debt asset
      (, address _pmDebt) = IPositionManager(_intent.properties.guardKey).assets();
      IRequestInteractions(newRequest).asset().checkAssetsMatch(_pmDebt);
    }

    // abandon the old request if it exists
    _facilityStorage.abandonRequest(_intent.request);

    // update the intent's request
    _intent.request = newRequest;
    emit RequestUpdated(id, newRequest);
  }
}

