// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {ReentrancyGuardTransient} from "lib/solady/src/utils/ReentrancyGuardTransient.sol";
import {FacilityRoles} from "./FacilityRoles.sol";
import {SafeTransferLib} from "lib/solady/src/utils/SafeTransferLib.sol";
import {IFacilityFunds} from "src/interfaces/facility/base/IFacilityFunds.sol";
import {IFund} from "src/interfaces/funds/IFund.sol";
import {LibIntent, Intent, BalanceSnapshot} from "src/libs/facility/LibIntent.sol";
import {LibStorage, FacilityStorageData} from "src/libs/facility/LibStorage.sol";
import {LibFacilityErrors} from "src/libs/facility/LibFacilityErrors.sol";
import {Order, Mode, State, LibOrder} from "src/libs/funds/Order.sol";

/// @title FacilityFunds
/// @author 3F Protocol
/// @notice Abstract contract implementing fund operations for intents.
/// @dev Allows creating, canceling, committing, unlocking, and recovering fund orders.
abstract contract FacilityFunds is IFacilityFunds, ReentrancyGuardTransient, FacilityRoles {
  using LibStorage for FacilityStorageData;
  using LibIntent for Intent;
  using SafeTransferLib for address;
  using LibOrder for Order;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           VIEWS                            */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityFunds
  function getOrder(uint256 id) external view override returns (Order memory order, bytes32 orderId) {
    Intent storage _intent = LibStorage.facilityStorage().getIntent(id);
    order = _intent.order;
    orderId = order.toId(_intent.fund);
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                        FUND OPERATIONS                     */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IFacilityFunds
  /// @dev Creates a fund order for the intent. The intent must be in resolving state
  ///      and must not have an active order. The order is stored in the intent for later operations.
  function create(uint256 id, uint256 amount, uint256 minAmountOut, Mode mode)
    external
    override
    onlyRoles(FACILITATOR_ROLE)
    nonReentrant
    returns (Order memory order)
  {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // checks that the intent has a fund
    address _fund = _intent.fund;
    if (_fund == address(0)) revert LibFacilityErrors.MissingFund(id);

    // ensure the intent has no pending order
    _intent.checkNoPendingOrder(id);

    // create order with a block/id unique salt
    order = Order({
      mode: mode,
      owner: address(this),
      receiver: address(this),
      input: amount,
      output: minAmountOut,
      salt: keccak256(abi.encode(address(this), block.timestamp, id))
    });
    emit CreatingOrder(id, order.toId(_fund));
    IFund(_fund).create(order);

    // update order in intent
    _intent.order = order;
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Cancels the current fund order for the intent.
  ///      The intent must have an active order.
  function cancel(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    // cancel order with the fund and delete it from the intent
    IFund(_intent.fund).cancel(_intent.order);
    _intent.removeOrderAndFund(id);
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Commits the current fund order for the intent.
  ///      Transfers the input tokens to the fund and calls commit on it.
  ///      The intent must have an active order.
  function commit(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    // get the order and token to deposit
    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    address _tokenIn = _order.mode == Mode.DEPOSIT ? IFund(_fund).asset() : IFund(_fund).share();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenIn);

    // commit the funds
    _tokenIn.safeApproveWithRetry(_fund, _order.input);
    (, uint256 _committedAmount) = IFund(_fund).commit(_order);
    if (_committedAmount != _order.input) {
      revert LibFacilityErrors.CommitAmountMismatch(id, _order.input, _committedAmount);
    }
    // reset approval to 0
    _tokenIn.safeApproveWithRetry(_fund, 0);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Unlocks the current fund order for the intent.
  ///      Receives the output tokens from the fund after successful processing.
  ///      Deletes the order if the state reaches ENDED.
  function unlock(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    // If this is the deposit, an unlock gives shares, otherwise it gives assets
    address _tokenOut = _order.mode == Mode.DEPOSIT ? IFund(_fund).share() : IFund(_fund).asset();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenOut);

    // unlock the funds
    (State _state,) = IFund(_fund).unlock(_order);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);

    if (_state == State.ENDED) {
      // if the order is ended, delete the order
      _intent.removeOrderAndFund(id);
    }
  }

  /// @inheritdoc IFacilityFunds
  /// @dev Recovers assets from the current fund order for the intent after failed processing.
  ///      Receives the input tokens back from the fund.
  ///      Deletes the order if the state reaches ENDED.
  function recover(uint256 id) external override onlyRoles(FACILITATOR_ROLE) nonReentrant {
    LibStorage.checkNotPaused();
    Intent storage _intent = LibStorage.facilityStorage().getResolvingIntent(id);

    // ensure the intent has an active order
    _intent.checkActiveOrder(id);

    Order memory _order = _intent.order;
    address _fund = _intent.fund;
    // If this is the deposit, a recover gives assets back, otherwise it gives shares back
    address _tokenIn = _order.mode == Mode.DEPOSIT ? IFund(_fund).asset() : IFund(_fund).share();

    // take snapshot before the operation
    BalanceSnapshot memory snapshot = LibIntent.takeBalanceSnapshot(_tokenIn);

    // recover the funds
    (State _state,) = IFund(_fund).recover(_order);

    // commit snapshot to record the balance change
    _intent.commitBalanceSnapshot(id, snapshot, _fund);

    if (_state == State.ENDED) {
      // if the order is ended, delete the order
      _intent.removeOrderAndFund(id);
    }
  }
}

lib/grunt/src/facility/base/FacilityRole.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {OwnableRoles} from "lib/solady/src/auth/OwnableRoles.sol";
import {SignatureCheckerLib} from "lib/solady/src/utils/SignatureCheckerLib.sol";
import {LibFacilityErrors} from "src/libs/facility/LibFacilityErrors.sol";
import {LibStorage, FacilityStorageData} from "src/libs/facility/LibStorage.sol";

/// @title FacilityRoles
/// @author 3F Protocol
/// @notice Facility role constants and shared guardian-signature quorum validation.
/// @dev Inherits OwnableRoles from solady for role-based access control.
abstract contract FacilityRoles is OwnableRoles {
  using LibStorage for FacilityStorageData;
  /// @notice Role for addresses authorized to facilitate intent operations.
  uint256 internal constant FACILITATOR_ROLE = _ROLE_0;

  /// @notice Role for addresses authorized to sign guardian-gated intents and swaps.
  uint256 internal constant GUARDIAN_ROLE = _ROLE_1;

  /// @notice Role for addresses authorized to pause/unpause the facility and revert deposits.
  uint256 internal constant COMPLIANCE_ROLE = _ROLE_2;

  /// @dev Verifies signatures against quorum and guardian-role constraints.
  ///      Signers must be sorted in strictly ascending order and unique.
  function _checkSignatures(
    FacilityStorageData storage _facilityStorage,
    bytes32 digest,
    address[] calldata signers,
    bytes[] calldata signatures,
    uint256 quorum
  ) internal {
    if (quorum == 0) return;
    _facilityStorage.checkDigest(digest);
    if (signers.length != signatures.length) revert LibFacilityErrors.InvalidSignatureLength();
    if (signers.length < quorum) revert LibFacilityErrors.InvalidSignatureCount(quorum, signers.length);

    address lastSigner;
    for (uint256 i = 0; i < quorum; i++) {
      address signer = signers[i];
      if (signer <= lastSigner) revert LibFacilityErrors.InvalidSignerOrder();
      if (!hasAnyRole(signer, GUARDIAN_ROLE)) revert LibFacilityErrors.NotGuardian(signer);
      if (!SignatureCheckerLib.isValidSignatureNowCalldata(signer, digest, signatures[i])) {
        revert LibFacilityErrors.InvalidSignature(signer);
      }
      lastSigner = signer;
    }
  }
}

lib/grunt/src/interfaces/request/IReques.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {Offer} from "./IOfferReceiver.sol";
import {IRequestInteractions} from "./IRequestInteractions.sol";

/// @title IRequest
/// @author 3F Protocol
/// @notice Interface for the Request contract that manages funding requests with dual-token (PT/YT) issuance.
interface IRequest is IRequestInteractions {
  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           EVENTS                           */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Emitted when the contract is marked as repaid, enabling withdrawals.
  /// @param amount The total amount of underlying assets available for redemption
  event Repaid(uint256 amount);

  /// @notice Emitted when funds are pulled from the contract.
  /// @param puller The address that pulled the funds
  /// @param amount The amount of underlying assets pulled
  event FundsPulled(address indexed puller, uint256 amount);

  /// @notice Emitted when minting authorization is granted to an address.
  /// @param to The address receiving minting authorization
  /// @param ptAmount The amount of PT tokens authorized to mint
  /// @param ytAmount The amount of YT tokens authorized to mint
  event AuthorizedMinting(address indexed to, uint256 ptAmount, uint256 ytAmount);

  /// @notice Emitted when the mint-to-repaid delay is updated.
  /// @param mintToRepaidDelay The new delay duration (seconds).
  event MintToRepaidDelaySet(uint40 mintToRepaidDelay);

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           ADMIN                            */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Marks the request as repaid, enabling withdrawals and redemptions.
  /// @param minBalance The minimum asset balance the contract must hold; reverts if below.
  /// @param maxBalance The maximum asset balance the contract must hold; reverts if above.
  ///                   Pass type(uint256).max to skip the upper bound check.
  function setRepaid(uint256 minBalance, uint256 maxBalance) external;

  /// @notice Syncs the repaid status after the repayment deadline has passed.
  /// @return repaid Whether the request is now marked as repaid
  function syncRepaidStatus() external returns (bool repaid);

  /// @notice Returns the timestamp of the last mint() or consume() call.
  /// @return The last mint timestamp (0 if no minting has occurred).
  function lastMintTimestamp() external view returns (uint40);

  /// @notice Returns the mint-to-repaid delay duration.
  /// @return The minimum delay (seconds) between the last mint/consume and setRepaid(uint256).
  function mintToRepaidDelay() external view returns (uint40);

  /// @notice Returns the earliest timestamp at which setRepaid(uint256) can be called.
  /// @return The timestamp at which setRepaid(uint256) becomes available (0 if no minting has occurred).
  function repaidAvailableAt() external view returns (uint40);

  /// @notice Sets the mint-to-repaid delay duration.
  /// @param mintToRepaidDelay_ The new delay (seconds).
  function setMintToRepaidDelay(uint40 mintToRepaidDelay_) external;

  /// @notice Authorizes an address to mint a specific amount of PT and YT tokens.
  /// @param to The address to authorize for minting
  /// @param ptAmount The amount of PT tokens the address can mint
  /// @param ytAmount The amount of YT tokens the address can mint
  function authorizeMinting(address to, uint128 ptAmount, uint128 ytAmount) external;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                          MINTING                           */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Returns the mint authorization for a given address.
  /// @param account The address to query mint authorization for
  /// @return ptAmount The amount of PT tokens the address is authorized to mint
  /// @return ytAmount The amount of YT tokens the address is authorized to mint
  function mintAuthorization(address account) external view returns (uint128 ptAmount, uint128 ytAmount);

  /// @notice Mints PT and YT tokens to the caller using their authorized amounts.
  /// @param maxPt The maximum PT amount the caller accepts (reverts if authorized PT > maxPt).
  ///             Pass type(uint128).max to skip the PT cap check.
  /// @param minYt The minimum YT amount the caller expects (reverts if authorized YT < minYt).
  function mint(uint128 maxPt, uint128 minYt) external;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                     OFFER CONSUMPTION                      */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Consumes a signed offer by minting PT/YT tokens to the offer maker.
  /// @param offer The signed offer struct containing maker, amount, expectedReturn, and other details
  /// @param signature The EIP-712 signature authorizing the offer
  /// @param ptAmount The amount of PT tokens to mint (must be <= offer.amount)
  /// @return ytAmount The amount of YT tokens minted to the offer maker
  function consume(Offer calldata offer, bytes calldata signature, uint256 ptAmount) external returns (uint256 ytAmount);
}

