// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

/// @title LibCommonErrors
/// @author 3F Protocol
/// @notice Common error definitions shared across all modules.
library LibCommonErrors {
  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
