// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {IPositionManager, SupplyQueueEntry} from "../interfaces/manager/IPositionManager.sol";
import {IPositionManagerAdmin} from "../interfaces/manager/base/IPositionManagerAdmin.sol";
import {ITransferGuard} from "../interfaces/guard/ITransferGuard.sol";
import {PositionManagerLP} from "./base/PositionManagerLP.sol";
import {PositionManagerAdmin} from "./base/PositionManagerAdmin.sol";
import {PositionManagerRebalancing} from "./base/PositionManagerRebalancing.sol";
import {
  FeeData,
  PositionManagerMetadata,
  PositionManagerStorageData,
  RebalanceConfig
} from "../libs/manager/LibStorage.sol";
import {LibStorage} from "../libs/manager/LibStorage.sol";
import {LibView} from "../libs/manager/LibView.sol";
import {LibManagerErrors} from "../libs/manager/LibManagerErrors.sol";
import {LibChecks} from "../libs/common/LibChecks.sol";
import {Initializable} from "lib/solady/src/utils/Initializable.sol";
import {EnumerableSetLib} from "lib/solady/src/utils/EnumerableSetLib.sol";
import {ERC20} from "lib/solady/src/tokens/ERC20.sol";
import {FixedPointMathLib} from "lib/solady/src/utils/FixedPointMathLib.sol";

/// @title PositionManager
/// @author 3F Protocol
/// @notice Aggregates multiple borrow positions into a single vault with share-based accounting.
/// @dev Uses supply/withdrawal queues for deposit/withdraw operations, implements fee accrual,
///      and uses virtual share offset for inflation attack protection.
contract PositionManager is
  IPositionManager,
  PositionManagerLP,
  PositionManagerAdmin,
  PositionManagerRebalancing,
  Initializable
{
  using EnumerableSetLib for EnumerableSetLib.AddressSet;
  using LibStorage for PositionManagerStorageData;
  using LibView for PositionManagerStorageData;
  using LibChecks for address;

  constructor() {
    _disableInitializers();
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                        INITIALIZATION                       */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Initializes the PositionManager.
  /// @param owner_ The owner of the contract
  /// @param metadata_ The metadata containing name, symbol, collateral and debt assets
  /// @param ltv_ The LTV for available collateral calculation (WAD precision)
  /// @param transferGuard_ The initial transfer guard address (address(0) to disable)
  /// @param maxRebalanceLoss_ The max rebalance loss in basis points (e.g., 100 = 1%)
  /// @param rebalanceCooldown_ The cooldown period in seconds between rebalance calls (0 = disabled)
  function initialize(
    address owner_,
    PositionManagerMetadata memory metadata_,
    uint256 ltv_,
    address transferGuard_,
    uint16 maxRebalanceLoss_,
    uint40 rebalanceCooldown_
  ) external initializer {
    owner_.checkNotZero();
    _initializeOwner(owner_);
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    _storage.metadata = metadata_;
    _storage.setLtv(ltv_);
    // Compute virtual share offset from debt asset decimals for inflation attack protection.
    // Uses zeroFloorSub to safely handle tokens with >18 decimals (offset becomes 10^0 = 1).
    // Safe: max exponent is 18, so 10^18 = 1e18 fits in uint64 (max ~1.8e19)
    // forge-lint: disable-next-line(unsafe-typecast)
    _storage.virtualShareOffset =
      uint64(10 ** FixedPointMathLib.zeroFloorSub(18, ERC20(metadata_.debtAsset).decimals()));
    // Safe: block.timestamp fits in uint40 for ~35,000 years
    // forge-lint: disable-next-line(unsafe-typecast)
    _storage.lastFeeAccrualTimestamp = uint40(block.timestamp);
    if (transferGuard_ != address(0)) {
      _storage.transferGuard = transferGuard_;
      emit IPositionManagerAdmin.TransferGuardSet(transferGuard_);
    }
    if (maxRebalanceLoss_ > 0 || rebalanceCooldown_ > 0) {
      _storage.setRebalanceConfig(maxRebalanceLoss_, rebalanceCooldown_);
    }
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           VIEW                              */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc ERC20
  function name() public view override returns (string memory) {
    return LibStorage.positionManagerStorage().metadata.name;
  }

  /// @inheritdoc ERC20
  function symbol() public view override returns (string memory) {
    return LibStorage.positionManagerStorage().metadata.symbol;
  }

  /// @inheritdoc IPositionManager
  function supplyQueue() public view returns (SupplyQueueEntry[] memory) {
    return LibStorage.positionManagerStorage().supplyQueue;
  }

  /// @inheritdoc IPositionManager
  function withdrawalQueue() public view returns (address[] memory) {
    return LibStorage.positionManagerStorage().withdrawalQueue;
  }

  /// @inheritdoc IPositionManager
  function borrowModules() public view returns (address[] memory) {
    return LibStorage.positionManagerStorage().borrowModules.values();
  }

  /// @inheritdoc IPositionManager
  function isBorrowModule(address module) public view returns (bool) {
    return LibStorage.positionManagerStorage().borrowModules.contains(module);
  }

  /// @inheritdoc IPositionManager
  function assets() public view returns (address collateralAsset, address debtAsset) {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    collateralAsset = _storage.metadata.collateralAsset;
    debtAsset = _storage.metadata.debtAsset;
  }

  /// @inheritdoc IPositionManager
  function collateralAmount() public view nonReadReentrant returns (uint256) {
    return LibStorage.positionManagerStorage().collateralAmount();
  }

  /// @inheritdoc IPositionManager
  function collateralAmountQuoted() public view nonReadReentrant returns (uint256) {
    return LibStorage.positionManagerStorage().collateralAmountQuoted();
  }

  /// @inheritdoc IPositionManager
  function debtAmount() public view nonReadReentrant returns (uint256) {
    return LibStorage.positionManagerStorage().debtAmount();
  }

  /// @inheritdoc IPositionManager
  function totalAssets() public view nonReadReentrant returns (uint256 amount) {
    (amount,,,) = LibStorage.positionManagerStorage().totalAssets();
  }

  /// @inheritdoc IPositionManager
  function hasBadDebt() public view nonReadReentrant returns (bool flag) {
    (,,, flag) = LibStorage.positionManagerStorage().totalAssets();
  }

  /// @inheritdoc ERC20
  /// @dev Reverts via {nonReadReentrant} when read during a deposit/withdraw/burn so external
  ///      integrators cannot observe a stale supply against a freshly-mutated NAV.
  function totalSupply() public view override nonReadReentrant returns (uint256) {
    return ERC20.totalSupply();
  }

  /// @inheritdoc IPositionManager
  function feeData()
    public
    view
    returns (
      address feeRecipient,
      uint24 managementFee,
      uint24 performanceFee,
      uint256 lastTotalAssets,
      uint256 lastFeeAccrualTimestamp,
      uint256 heldManagementFees
    )
  {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    FeeData memory fd = _storage.feeData;
    feeRecipient = fd.feeRecipient;
    managementFee = fd.managementFee;
    performanceFee = fd.performanceFee;
    lastTotalAssets = _storage.lastTotalAssets;
    lastFeeAccrualTimestamp = _storage.lastFeeAccrualTimestamp;
    heldManagementFees = _storage.heldManagementFeeAssets;
  }

  /// @inheritdoc IPositionManager
  function lastDebt() public view returns (uint256) {
    return LibStorage.positionManagerStorage().lastDebt;
  }

  /// @inheritdoc IPositionManager
  function pendingFees()
    public
    view
    nonReadReentrant
    returns (uint256 totalAssets_, uint256 totalSupply_, uint256 managementFeeShares, uint256 performanceFeeShares)
  {
    (totalAssets_, totalSupply_,, managementFeeShares, performanceFeeShares,,) = _pendingFees();
  }

  /// @inheritdoc IPositionManager
  function virtualShareOffset() public view returns (uint256) {
    return LibStorage.positionManagerStorage().virtualShareOffset;
  }

  /// @inheritdoc IPositionManager
  function config() public view returns (uint256 ltv, address transferGuard) {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    ltv = _storage.ltv;
    transferGuard = _storage.transferGuard;
  }

  /// @inheritdoc IPositionManager
  function rebalanceConfig()
    public
    view
    returns (uint16 maxRebalanceLoss, uint40 rebalanceCooldown, uint40 lastRebalanceTimestamp)
  {
    RebalanceConfig storage rc = LibStorage.positionManagerStorage().rebalanceConfig;
    maxRebalanceLoss = rc.maxRebalanceLoss;
    rebalanceCooldown = rc.rebalanceCooldown;
    lastRebalanceTimestamp = rc.lastRebalanceTimestamp;
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                    INTERNAL OVERRIDES                       */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc ERC20
  /// @dev Validates transfers through the transfer guard if one is set.
  ///      Reverts with {LibManagerErrors.TransferBlocked} if the transfer is blocked by the guard.
  function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
    address guard = LibStorage.positionManagerStorage().transferGuard;
    if (guard != address(0)) {
      if (!ITransferGuard(guard).canTransfer(address(this), from, to, amount)) {
        revert LibManagerErrors.TransferBlocked();
      }
    }
  }
}

lib/grunt/src/interfaces/manager/IPositi.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {IPositionManagerAdmin, SupplyQueueEntry} from "./base/IPositionManagerAdmin.sol";
import {IPositionManagerRebalancing} from "./base/IPositionManagerRebalancing.sol";
import {IPositionManagerLP} from "./base/IPositionManagerLP.sol";

/// @title IPositionManager
/// @author 3F Protocol
/// @notice Interface for the PositionManager contract that aggregates multiple borrow positions
///         (IBorrowPosition) into a single unified interface. The PositionManager allows the owner
///         to combine operations across multiple borrowing protocols (e.g., Morpho, Euler, etc.)
///         and manage them as a single position. This enables more complex strategies that leverage
///         multiple lending markets simultaneously while presenting a simplified interface to users.
interface IPositionManager is IPositionManagerAdmin, IPositionManagerRebalancing, IPositionManagerLP {
  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           VIEW                             */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Returns the supply queue used for deposits.
  /// @return Array of SupplyQueueEntry structs (position address + max borrow)
  function supplyQueue() external view returns (SupplyQueueEntry[] memory);

  /// @notice Returns the withdrawal queue used for withdrawals.
  /// @return Array of position addresses in withdrawal order
  function withdrawalQueue() external view returns (address[] memory);

  /// @notice Returns all whitelisted borrow modules.
  /// @return Array of borrow module addresses
  function borrowModules() external view returns (address[] memory);

  /// @notice Checks if an address is a whitelisted borrow module.
  /// @param module The address to check
  /// @return True if the address is a whitelisted borrow module
  function isBorrowModule(address module) external view returns (bool);

  /// @notice Returns the collateral and debt asset addresses.
  /// @return collateralAsset The address of the collateral asset token
  /// @return debtAsset The address of the debt asset token
  function assets() external view returns (address collateralAsset, address debtAsset);

  /// @notice Returns the total amount of collateral across all borrow positions.
  /// @dev The collateral is in raw collateral asset units.
  /// @return The total collateral amount across all positions
  function collateralAmount() external view returns (uint256);

  /// @notice Returns the total amount of collateral quoted in debt asset terms.
  /// @dev Uses each position's oracle to convert collateral to debt asset value.
  /// @return The total collateral value in debt asset terms
  function collateralAmountQuoted() external view returns (uint256);

  /// @notice Returns the total amount of debt across all borrow positions.
  /// @dev The debt represents the total borrowed amount across all aggregated positions.
  /// @return The total debt amount across all positions
  function debtAmount() external view returns (uint256);

  /// @notice Returns the total assets (collateral value - debt) of the position manager.
  /// @dev This is the net value that determines share pricing. Borrow modules whose debt exceeds
  ///      their quoted collateral are excluded entirely from the sum, so while {hasBadDebt}
  ///      returns true this value covers only the solvent modules.
  /// @return The total assets value in debt asset terms
  function totalAssets() external view returns (uint256);

  /// @notice Returns the bad-debt exclusion flag.
  /// @dev True when at least one borrow module is underwater (debt exceeds quoted collateral)
  ///      and is therefore excluded from {totalAssets} and the fee bases. Sourced from the same
  ///      single-pass module iteration as {totalAssets} (see `LibView.totalAssets`). The
  ///      `collateral >= debt` inclusion test is a one-wei-wide cliff: an excluded module
  ///      re-enters once its full `debt - collateral` shortfall is repaid on the underlying
  ///      market, which anyone can do (a single base unit when the module is underwater by
  ///      exactly one unit). Reverts when any module's quote reverts (e.g. an oracle outage),
  ///      so monitors must treat a revert as "unknown", not as "no bad debt".
  /// @return True when the aggregates reported by {totalAssets} cover only the solvent modules
  function hasBadDebt() external view returns (bool);

  /// @notice Returns the fee configuration and accounting state.
  /// @dev `lastTotalAssets` is the NAV component (`refCollat - refDebt`) of the performance
  ///      reference. To reconstruct the reference collateral
  ///      `lastCollat = lastTotalAssets + lastDebt`, read `lastDebt()` alongside this value. The
  ///      reference advances to the current state only when a positive basis crystallizes; while
  ///      it is held (non-positive basis) or after flow rebases it deviates from the live NAV by
  ///      the carried pending basis (or sits below it by a preserved pending gain).
  /// @return feeRecipient The address that receives fee payments
  /// @return managementFee The management fee rate in basis points per 365 days, charged on the
  ///         aggregate collateral of non-bad-debt positions (not NAV) and capped at `totalAssets`.
  ///         Eligibility is checkpoint-end: a module inside the `collateral >= debt` filter at
  ///         accrual time is charged on its full collateral for the whole elapsed interval,
  ///         regardless of when it (re-)entered (re-inclusion costs the module's full
  ///         `debt - collateral` shortfall — see {hasBadDebt}).
  /// @return performanceFee The performance fee rate in basis points (charged on net levered-slice
  ///         gains after mgmt fee — see {pendingFees} / NatSpec on `_pendingFees`).
  /// @return lastTotalAssets The NAV component of the performance reference used for fee accounting
  /// @return lastFeeAccrualTimestamp The timestamp of the last fee accrual
  /// @return heldManagementFees The management fee assets charged and not yet netted against a
  ///         crystallized performance basis, deducted from the next positive basis (a
  ///         crystallizing advance consumes it up to the basis and carries the excess; a
  ///         bootstrap/empty-vault reseed, a flow that burns the last share, and
  ///         `resetPerformanceReference` clear it). This value is asset-denominated and can be
  ///         non-zero even when no fee shares are pending or minted.
  function feeData()
    external
    view
    returns (
      address feeRecipient,
      uint24 managementFee,
      uint24 performanceFee,
      uint256 lastTotalAssets,
      uint256 lastFeeAccrualTimestamp,
      uint256 heldManagementFees
    );

  /// @notice Returns the debt component of the performance reference.
  /// @dev Combined with `feeData().lastTotalAssets`, callers can reconstruct
  ///      `lastCollat = lastTotalAssets + lastDebt`. While the reference is held (non-positive
  ///      pending basis) this is lower than the live debt by the carried debt cost, or above
  ///      it by a preserved pending gain (see `LibStorage.rebaseSnapshot`). A value of
  ///      zero is the bootstrap sentinel and means the next accrual will skip the performance fee
  ///      and seed this slot.
  /// @return The reference debt for the performance-fee basis
  function lastDebt() external view returns (uint256);

  /// @notice Returns the pending fee data needed to compute an accurate share price.
  /// @dev Mirrors the logic of the internal `_accrueFees()` function without mutating state.
  ///      Integrators can compute an accurate share price as:
  ///      `price = totalAssets / (totalSupply + managementFeeShares + performanceFeeShares)`.
  ///      Zero returned shares do not prove that fee state is empty: the fee cap can suppress a
  ///      mint or share conversion can round down. On accrual the timestamp still advances, the
  ///      reference follows its advance/hold rule, and `feeData().heldManagementFees` may remain.
  /// @return totalAssets_ The current total assets (collateral value - debt) across all borrow modules
  /// @return totalSupply_ The current total supply of shares (excluding pending fee shares)
  /// @return managementFeeShares The shares that would be minted for management fees
  /// @return performanceFeeShares The shares that would be minted for performance fees
  function pendingFees()
    external
    view
    returns (uint256 totalAssets_, uint256 totalSupply_, uint256 managementFeeShares, uint256 performanceFeeShares);

  /// @notice Returns the virtual share offset used for inflation attack protection.
  /// @dev Derived from the debt asset decimals: 10^(18 - debtAsset.decimals()), floored at 1.
  /// @return The virtual share offset value
  function virtualShareOffset() external view returns (uint256);

  /// @notice Returns the configuration parameters.
  /// @return ltv The LTV used for available collateral calculations (WAD precision)
  /// @return transferGuard The address of the transfer guard contract (address(0) if disabled)
  function config() external view returns (uint256 ltv, address transferGuard);

  /// @notice Returns the rebalance configuration and state.
  /// @return maxRebalanceLoss The maximum allowed loss during rebalance in basis points
  /// @return rebalanceCooldown The minimum seconds between consecutive rebalance calls (0 = disabled)
  /// @return lastRebalanceTimestamp The timestamp of the last rebalance call (0 if never rebalanced)
  function rebalanceConfig()
    external
    view
    returns (uint16 maxRebalanceLoss, uint40 rebalanceCooldown, uint40 lastRebalanceTimestamp);
}

