// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

/// @notice Status of an address in the transfer guard.
/// @dev NONE must be 0 so unset mappings default to the token's mode behavior.
enum AddressStatus {
  /// @notice Not explicitly set - behavior depends on token mode.
  NONE,
  /// @notice Explicitly whitelisted - allowed in all modes except as sole party in NATIVE modes.
  WHITELIST,
  /// @notice Explicitly blocklisted - blocked in all modes.
  BLOCKLIST,
  /// @notice Protocol-native address (e.g., Facility). Implicitly whitelisted and satisfies NATIVE mode requirements.
  NATIVE
}

/// @notice Per-token transfer mode in the transfer guard.
enum TokenMode {
  /// @notice Default: all addresses allowed except BLOCKLIST.
  BLOCKLIST,
  /// @notice Only WHITELIST or NATIVE addresses allowed.
  WHITELIST,
  /// @notice At least one party must be NATIVE, no BLOCKLIST allowed. Mints/burns bypass NATIVE requirement.
  NATIVE_ONLY,
  /// @notice All parties must be WHITELIST/NATIVE, at least one NATIVE. Mints/burns bypass NATIVE requirement.
  NATIVE_WHITELIST
}

/// @title ITransferGuard
/// @author 3F Protocol
/// @notice Interface for transfer validation and pause functionality.
/// @dev Implementations can enforce blocklists, allowlists, transfer thresholds, or any custom logic.
interface ITransferGuard {
  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                          EVENTS                            */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Emitted when an address status is updated.
  /// @param account The address whose status was updated
  /// @param status The new status
  event AddressStatusSet(address indexed account, AddressStatus status);

  /// @notice Emitted when a token's configuration is updated.
  /// @param token The token address
  /// @param pausedUntil The pause-until timestamp (0 = not paused, type(uint40).max = permanent)
  /// @param mode The token's transfer mode
  /// @param checkCollateralAllowed Whether to check collateral asset's isAllowed
  event TokenConfigSet(address indexed token, uint40 pausedUntil, TokenMode mode, bool checkCollateralAllowed);

  /// @notice Emitted when a token's pause state is updated.
  /// @param token The token address
  /// @param pausedUntil The pause-until timestamp (0 = not paused, type(uint40).max = permanent)
  event TokenPausedSet(address indexed token, uint40 pausedUntil);

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                       VIEW FUNCTIONS                       */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @notice Checks if a transfer is allowed between two addresses.
  /// @dev Called by token contracts before executing transfers, mints, and burns.
  ///      For mints, `from` is address(0). For burns, `to` is address(0).
  /// @param token The token being transferred (allows one guard to serve multiple tokens)
  /// @param from The sender address (address(0) for mints)
  /// @param to The recipient address (address(0) for burns)
  /// @param amount The amount being transferred
  /// @return True if the transfer is allowed, false otherwise
  function canTransfer(address token, address from, address to, uint256 amount) external view returns (bool);

  /// @notice Returns whether operations are paused for a specific token.
  /// @dev When paused, all transfers should be blocked and other guarded operations should revert.
  /// @param token The token to check pause status for
  /// @return True if paused, false otherwise
  function paused(address token) external view returns (bool);
}

lib/grunt/src/manager/base/PositionManag.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {IPositionManagerLP} from "../../interfaces/manager/base/IPositionManagerLP.sol";
import {ITransferGuard} from "../../interfaces/guard/ITransferGuard.sol";
import {WithdrawalStrategy} from "../../interfaces/manager/base/IPositionManagerAdmin.sol";
import {PositionManagerBase} from "./PositionManagerBase.sol";
import {PositionManagerStorageData} from "../../libs/manager/LibStorage.sol";
import {LibStorage} from "../../libs/manager/LibStorage.sol";
import {LibOperations} from "../../libs/manager/LibOperations.sol";
import {LibView} from "../../libs/manager/LibView.sol";
import {LibExecutor} from "../../libs/manager/LibExecutor.sol";
import {LibManagerErrors} from "../../libs/manager/LibManagerErrors.sol";
import {LibCommonErrors as CommonErrors} from "../../libs/common/LibCommonErrors.sol";
import {SafeTransferLib} from "lib/solady/src/utils/SafeTransferLib.sol";
import {FixedPointMathLib} from "lib/solady/src/utils/FixedPointMathLib.sol";
import {EnumerableSetLib} from "lib/solady/src/utils/EnumerableSetLib.sol";
import {ERC20} from "lib/solady/src/tokens/ERC20.sol";

/// @title PositionManagerLP
/// @author 3F Protocol
/// @notice Abstract contract handling LP operations (deposit, withdraw, burn) for PositionManager.
/// @dev Inherits PositionManagerBase for roles, fee accrual, and reentrancy protection.
abstract contract PositionManagerLP is IPositionManagerLP, PositionManagerBase {
  using SafeTransferLib for address;
  using FixedPointMathLib for uint256;
  using LibExecutor for address;
  using LibStorage for PositionManagerStorageData;
  using LibOperations for PositionManagerStorageData;
  using LibView for PositionManagerStorageData;
  using LibView for uint256;
  using EnumerableSetLib for EnumerableSetLib.AddressSet;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                        OPERATIONS                          */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IPositionManagerLP
  /// @dev Reverts with {LibCommonErrors.AmountZero} if both collateral and debt are zero.
  ///      Reverts with {LibManagerErrors.EmptySupplyQueue} if debt is zero but collateral > 0 and supply queue is empty.
  function deposit(uint256 collateral, uint256 debt)
    external
    onlyRoles(MINTER_ROLE)
    nonReentrant
    returns (int256 shares)
  {
    if (collateral == 0 && debt == 0) revert CommonErrors.AmountZero();

    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Accrue fees and get current total assets and debt.
    // Use ERC20.totalSupply() to bypass the nonReadReentrant override on the public totalSupply().
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();
    uint256 _totalSupply = ERC20.totalSupply();

    // Pull collateral from caller
    if (collateral > 0) {
      _storage.metadata.collateralAsset.safeTransferFrom(msg.sender, address(this), collateral);
    }

    // Process deposits through supply queue
    if (debt == 0) {
      // No debt: deposit all collateral to first position
      if (collateral > 0) {
        if (_storage.supplyQueue.length == 0) revert LibManagerErrors.EmptySupplyQueue();
        _storage.supplyQueue[0].position.supply(_storage.metadata.collateralAsset, collateral);
      }
    } else {
      // With debt: iterate through queue
      _storage.processDeposit(collateral, debt);
    }

    // Settle shares based on assets delta before any external transfer to keep
    // totalAssets() and totalSupply() consistent during outbound calls.
    shares = _settleShares(totalAssetsBefore, debtBefore, _totalSupply);

    // Send borrowed debt to caller
    if (debt > 0) {
      _storage.metadata.debtAsset.safeTransfer(msg.sender, debt);
    }

    emit Deposit(msg.sender, collateral, debt, shares);
  }

  /// @inheritdoc IPositionManagerLP
  /// @dev Reverts with {LibCommonErrors.AmountZero} if both collateral and debt are zero.
  function withdraw(uint256 collateral, uint256 debt, WithdrawalStrategy strategy)
    external
    onlyRoles(MINTER_ROLE)
    nonReentrant
    returns (int256 shares)
  {
    if (collateral == 0 && debt == 0) revert CommonErrors.AmountZero();

    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Accrue fees and get current total assets and debt.
    // Use ERC20.totalSupply() to bypass the nonReadReentrant override on the public totalSupply().
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();
    uint256 _totalSupply = ERC20.totalSupply();

    // Pull debt from caller for repayment
    if (debt > 0) {
      _storage.metadata.debtAsset.safeTransferFrom(msg.sender, address(this), debt);
    }

    // Process withdrawals through withdrawal queue using the specified strategy
    // checkLtv=true: proportional withdrawals must respect per-position LTV bounds
    _storage.processWithdrawal(collateral, debt, strategy, true);

    // Settle shares based on assets delta before any external transfer to keep
    // totalAssets() and totalSupply() consistent during outbound calls.
    shares = _settleShares(totalAssetsBefore, debtBefore, _totalSupply);

    // Send collateral to caller
    if (collateral > 0) {
      _storage.metadata.collateralAsset.safeTransfer(msg.sender, collateral);
    }

    emit Withdraw(msg.sender, collateral, debt, shares);
  }

  /// @inheritdoc IPositionManagerLP
  /// @dev Reverts with {LibCommonErrors.AmountZero} if shares is zero.
  function burn(uint256 shares, WithdrawalStrategy strategy)
    external
    onlyRoles(MINTER_ROLE)
    nonReentrant
    returns (uint256 collateral, uint256 debt)
  {
    if (shares == 0) revert CommonErrors.AmountZero();

    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Accrue fees first and capture the pre-flow state for the reference rebase.
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();

    // Use ERC20.totalSupply() to bypass the nonReadReentrant override on the public totalSupply().
    uint256 _totalSupply = ERC20.totalSupply();
    uint256 _totalCollateral = _storage.collateralAmount();
    uint256 _totalDebt = _storage.debtAmount();
    uint256 virtualShareOffset_ = _storage.virtualShareOffset;

    // Calculate proportional amounts to maintain average LTV.
    // Include virtualShareOffset in the denominator so that virtual shares absorb their
    // proportional fraction of collateral/debt, preventing extraction of donated assets
    // that inflate totalAssets without minting shares.
    // Round down collateral (user gets less), round up debt (user repays more)
    collateral = _totalCollateral.mulDiv(shares, _totalSupply + virtualShareOffset_);
    debt = _totalDebt.mulDivUp(shares, _totalSupply + virtualShareOffset_);

    // Burn shares first
    _burn(msg.sender, shares);

    // Pull debt from caller for repayment
    if (debt > 0) {
      _storage.metadata.debtAsset.safeTransferFrom(msg.sender, address(this), debt);
    }

    // Process through withdrawal queue using the specified strategy.
    // When the withdrawal queue covers all whitelisted positions, burn amounts are proportional
    // to total debt/collateral so per-position LTV is maintained by construction — skip the check.
    // When the queue is a strict subset, some positions are excluded from the proportional
    // distribution, so queue positions may bear a disproportionate share of the withdrawal
    // and per-position LTV checks are required.
    bool skipLtvCheck = _storage.withdrawalQueue.length == _storage.borrowModules.length();
    _storage.processWithdrawal(collateral, debt, strategy, !skipLtvCheck);

    // Rebase the performance reference across the flow so the exiting shares take their
    // proportional slice of any carried pending basis with them. Rebased before the outgoing
    // transfer so a token callback cannot move module state into the new reference; the
    // transfer itself changes nothing the rebase reads (module aggregates only).
    _rebaseReference(totalAssetsBefore, debtBefore, _totalSupply);

    // Send collateral to caller
    if (collateral > 0) {
      _storage.metadata.collateralAsset.safeTransfer(msg.sender, collateral);
    }

    emit Burn(msg.sender, shares, collateral, debt);
  }

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                    SHARE CALCULATIONS                       */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @dev Settles share changes based on total assets delta.
  ///      Mints shares if assets increased, burns shares if assets decreased.
  /// @param totalAssetsBefore The total assets before the operation
  /// @param debtBefore The aggregate good-debt debt before the operation (post fee accrual),
  ///        needed to rebase the performance reference across the flow
  /// @param _totalSupply The total supply before the operation
  /// @return sharesDelta Positive if shares minted, negative if shares burned
  function _settleShares(uint256 totalAssetsBefore, uint256 debtBefore, uint256 _totalSupply)
    internal
    returns (int256 sharesDelta)
  {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    (uint256 totalAssetsAfter, uint256 debtAfter, uint256 collatAfter,) = _storage.totalAssets();
    uint256 virtualShareOffset_ = _storage.virtualShareOffset;

    if (totalAssetsAfter > totalAssetsBefore) {
      // Assets increased: mint shares to caller
      uint256 assetsAdded = totalAssetsAfter - totalAssetsBefore;
      uint256 sharesToMint = assetsAdded.convertToShares(_totalSupply, totalAssetsBefore, virtualShareOffset_, false);
      if (sharesToMint > 0) {
        _mint(msg.sender, sharesToMint);
        // Safe: sharesToMint is capped by total supply which fits in uint128
        // forge-lint: disable-next-line(unsafe-typecast)
        sharesDelta = int256(sharesToMint);
      } else {
        // Shares rounded to zero: run the transfer guard since _beforeTokenTransfer won't.
        address guard = _storage.transferGuard;
        if (guard != address(0) && !ITransferGuard(guard).canTransfer(address(this), msg.sender, msg.sender, 0)) {
          revert LibManagerErrors.TransferBlocked();
        }
      }
    } else if (totalAssetsAfter < totalAssetsBefore) {
      // Assets decreased: burn shares from caller
      uint256 assetsRemoved = totalAssetsBefore - totalAssetsAfter;
      uint256 sharesToBurn = assetsRemoved.convertToShares(_totalSupply, totalAssetsBefore, virtualShareOffset_, true);
      _burn(msg.sender, sharesToBurn);
      // Safe: sharesToBurn is capped by total supply which fits in uint128
      // forge-lint: disable-next-line(unsafe-typecast)
      sharesDelta = -int256(sharesToBurn);
    } else {
      // Assets unchanged: no mint/burn, but run the transfer guard since _beforeTokenTransfer won't.
      address guard = _storage.transferGuard;
      if (guard != address(0) && !ITransferGuard(guard).canTransfer(address(this), msg.sender, msg.sender, 0)) {
        revert LibManagerErrors.TransferBlocked();
      }
    }
    // If sharesToMint rounds to 0 or assets are equal, sharesDelta remains 0

    // Rebase the performance reference across the flow (preserves the pending basis, so
    // accrued debt carry and any held entitlement survive the flow).
    _storage.rebaseSnapshot(
      totalAssetsBefore + debtBefore, debtBefore, _totalSupply, collatAfter, debtAfter, ERC20.totalSupply()
    );
  }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {IPositionManagerAdmin, SupplyQueueEntry} from "../../interfaces/manager/base/IPositionManagerAdmin.sol";
import {IBorrowPosition} from "../../interfaces/borrow/IBorrowPosition.sol";
import {PositionManagerBase} from "./PositionManagerBase.sol";
import {FeeData, PositionManagerStorageData} from "../../libs/manager/LibStorage.sol";
import {LibStorage} from "../../libs/manager/LibStorage.sol";
import {LibManagerErrors} from "../../libs/manager/LibManagerErrors.sol";
import {MAX_MANAGEMENT_FEE, MAX_PERFORMANCE_FEE} from "../../libs/manager/LibConstants.sol";
import {Ownable} from "lib/solady/src/auth/Ownable.sol";
import {EnumerableSetLib} from "lib/solady/src/utils/EnumerableSetLib.sol";
import {ERC20} from "lib/solady/src/tokens/ERC20.sol";

/// @title PositionManagerAdmin
/// @author 3F Protocol
/// @notice Abstract contract handling administrative functions for PositionManager.
/// @dev Manages borrow modules, supply/withdrawal queues, LTV, and max rebalance loss.
abstract contract PositionManagerAdmin is IPositionManagerAdmin, PositionManagerBase {
  using EnumerableSetLib for EnumerableSetLib.AddressSet;
  using LibStorage for PositionManagerStorageData;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                           ADMIN                             */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Accrues fees before adding the module to checkpoint totalAssets.
  ///      Rebases the performance reference (`lastTotalAssets` and `lastDebt`) after adding via
  ///      `rebaseSnapshot`, so the new module's assets and debt enter the next fee period's basis
  ///      as a flow (any carried pending basis is preserved, not written off).
  ///      Validates that the module's collateral and debt assets match the position manager's,
  ///      the module's owner is this contract, and the module's safe LTV is >= the PM LTV.
  function addBorrowModule(address module) external override onlyOwner {
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    if (IBorrowPosition(module).collateralAsset() != _storage.metadata.collateralAsset) {
      revert LibManagerErrors.CollateralAssetMismatch();
    }
    if (IBorrowPosition(module).borrowAsset() != _storage.metadata.debtAsset) {
      revert LibManagerErrors.DebtAssetMismatch();
    }
    if (Ownable(module).owner() != address(this)) {
      revert LibManagerErrors.InvalidModuleOwner();
    }
    if (IBorrowPosition(module).safeLtv() < _storage.ltv) {
      revert LibManagerErrors.ModuleSafeLtvTooLow();
    }

    if (!_storage.borrowModules.add(module)) {
      revert LibManagerErrors.ModuleAlreadyAdded();
    }
    // Supply-neutral flow: any carried pending basis is preserved against the new module set.
    _rebaseReference(totalAssetsBefore, debtBefore, ERC20.totalSupply());
    emit IPositionManagerAdmin.BorrowModuleAdded(module);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Accrues fees before removing the module to checkpoint totalAssets.
  ///      Rebases the performance reference (`lastTotalAssets` and `lastDebt`) after removing via
  ///      `rebaseSnapshot`, so the removed module's assets and debt leave the next fee period's
  ///      basis as a flow (any carried pending basis is preserved, not written off).
  ///      Reverts with {LibManagerErrors.ModuleStillInQueue} if the module is still in supply or withdrawal queue.
  function removeBorrowModule(address module) external override onlyOwner {
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Check module is not in supply queue
    uint256 supplyQueueLength = _storage.supplyQueue.length;
    for (uint256 i = 0; i < supplyQueueLength; ++i) {
      if (_storage.supplyQueue[i].position == module) revert LibManagerErrors.ModuleStillInQueue();
    }

    // Check module is not in withdrawal queue
    uint256 withdrawalQueueLength = _storage.withdrawalQueue.length;
    for (uint256 i = 0; i < withdrawalQueueLength; ++i) {
      if (_storage.withdrawalQueue[i] == module) revert LibManagerErrors.ModuleStillInQueue();
    }

    if (!_storage.borrowModules.remove(module)) {
      revert LibManagerErrors.ModuleNotFound();
    }
    // Supply-neutral flow: any carried pending basis is preserved against the new module set.
    _rebaseReference(totalAssetsBefore, debtBefore, ERC20.totalSupply());
    Ownable(module).transferOwnership(msg.sender);
    emit IPositionManagerAdmin.BorrowModuleRemoved(module);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Reverts with {LibManagerErrors.UnauthorizedPosition} if any position in the queue is not whitelisted.
  ///      Reverts with {LibManagerErrors.DuplicateQueueEntry} if any position appears more than once.
  function setSupplyQueue(SupplyQueueEntry[] calldata queue) external override onlyRoles(CURATOR_ROLE) {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    delete _storage.supplyQueue;
    uint256 queueLength = queue.length;
    for (uint256 i = 0; i < queueLength; ++i) {
      if (!_storage.borrowModules.contains(queue[i].position)) revert LibManagerErrors.UnauthorizedPosition();
      for (uint256 j = 0; j < i; ++j) {
        if (queue[j].position == queue[i].position) revert LibManagerErrors.DuplicateQueueEntry();
      }
      _storage.supplyQueue.push(queue[i]);
    }
    emit IPositionManagerAdmin.SupplyQueueSet(queue);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Reverts with {LibManagerErrors.UnauthorizedPosition} if any position in the queue is not whitelisted.
  ///      Reverts with {LibManagerErrors.DuplicateQueueEntry} if any position appears more than once.
  function setWithdrawalQueue(address[] calldata queue) external override onlyRoles(CURATOR_ROLE) {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    uint256 queueLength = queue.length;
    for (uint256 i = 0; i < queueLength; ++i) {
      if (!_storage.borrowModules.contains(queue[i])) revert LibManagerErrors.UnauthorizedPosition();
      for (uint256 j = 0; j < i; ++j) {
        if (queue[j] == queue[i]) revert LibManagerErrors.DuplicateQueueEntry();
      }
    }
    _storage.withdrawalQueue = queue;
    emit IPositionManagerAdmin.WithdrawalQueueSet(queue);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Reverts with {LibManagerErrors.ModuleSafeLtvTooLow} if any whitelisted borrow module
  ///      has a safe LTV lower than the new PM LTV.
  ///      Reverts with {LibCommonErrors.InvalidLtv} (via setLtv) if ltv is zero or greater than WAD.
  function setLtv(uint256 ltv_) external override onlyOwner {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Check all whitelisted borrow modules have safeLtv >= new PM LTV
    uint256 len = _storage.borrowModules.length();
    for (uint256 i; i < len; ++i) {
      if (IBorrowPosition(_storage.borrowModules.at(i)).safeLtv() < ltv_) {
        revert LibManagerErrors.ModuleSafeLtvTooLow();
      }
    }

    _storage.setLtv(ltv_);
  }

  /// @inheritdoc IPositionManagerAdmin
  function setRebalanceConfig(uint16 maxRebalanceLoss_, uint40 rebalanceCooldown_) external override onlyOwner {
    LibStorage.positionManagerStorage().setRebalanceConfig(maxRebalanceLoss_, rebalanceCooldown_);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Setting transferGuard_ to address(0) disables transfer restrictions,
  ///      allowing all transfers without validation. This is intentional behavior.
  function setTransferGuard(address transferGuard_) external override onlyOwner {
    LibStorage.positionManagerStorage().transferGuard = transferGuard_;
    emit IPositionManagerAdmin.TransferGuardSet(transferGuard_);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Reverts with {LibManagerErrors.FeeExceedsMax} if management or performance fee exceeds the maximum.
  function setFeeData(address feeRecipient, uint24 managementFee, uint24 performanceFee) external override onlyOwner {
    if (managementFee > MAX_MANAGEMENT_FEE || performanceFee > MAX_PERFORMANCE_FEE) {
      revert LibManagerErrors.FeeExceedsMax();
    }

    // Accrue fees to current recipient first
    _accrueFees();

    FeeData memory fd;
    fd.feeRecipient = feeRecipient;
    fd.managementFee = managementFee;
    fd.performanceFee = performanceFee;
    LibStorage.positionManagerStorage().feeData = fd;

    emit IPositionManagerAdmin.FeeDataSet(feeRecipient, managementFee, performanceFee);
  }

  /// @inheritdoc IPositionManagerAdmin
  /// @dev Accrues fees first: a positive pending basis crystallizes normally before the reference
  ///      moves (a held entitlement that rounds to zero fee shares is forgiven without minting),
  ///      so the reset never mints on past gains; it only forgives the carried negative
  ///      basis going forward. The forgiven carry includes the debt interest accrued since the
  ///      last crystallization, which the next positive accrual will no longer net (see the
  ///      interface timing note: reset as soon as possible after a positive charge). While every
  ///      position is excluded as bad debt the aggregates read (0, 0), so a reset writes the
  ///      bootstrap sentinel and the next accrual reseeds the reference at whatever state it
  ///      observes. When only some positions are excluded, the reset anchors on the reduced
  ///      good-debt universe: an excluded module recovering later re-enters the basis as new gain
  ///      and is charged (the reset accepted that module's loss).
  function resetPerformanceReference() external override onlyOwner {
    (uint256 currentTotalAssets, uint256 currentDebt) = _accrueFees();
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();
    _storage.lastTotalAssets = currentTotalAssets;
    _storage.lastDebt = currentDebt;
    // The reset starts a fresh fee period, so the pending management fee deduction (management
    // fees charged and not yet netted against a crystallized basis, including the interval
    // settled by the accrual above) is forgiven along with the carried basis.
    _storage.heldManagementFeeAssets = 0;
    emit IPositionManagerAdmin.PerformanceReferenceReset(currentTotalAssets, currentDebt);
  }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.22;

import {
  IPositionManagerRebalancing,
  RebalancingData,
  RebalancingOperation,
  RebalancingOperationType
} from "../../interfaces/manager/base/IPositionManagerRebalancing.sol";
import {ITransferGuard} from "../../interfaces/guard/ITransferGuard.sol";
import {PositionManagerBase} from "./PositionManagerBase.sol";
import {PositionManagerStorageData} from "../../libs/manager/LibStorage.sol";
import {LibStorage} from "../../libs/manager/LibStorage.sol";
import {LibManagerErrors} from "../../libs/manager/LibManagerErrors.sol";
import {LibCommonErrors as CommonErrors} from "../../libs/common/LibCommonErrors.sol";
import {EnumerableSetLib} from "lib/solady/src/utils/EnumerableSetLib.sol";
import {LibView} from "../../libs/manager/LibView.sol";
import {BPS} from "../../libs/Constants.sol";
import {LibExecutor} from "../../libs/manager/LibExecutor.sol";
import {SafeTransferLib} from "lib/solady/src/utils/SafeTransferLib.sol";
import {ERC20} from "lib/solady/src/tokens/ERC20.sol";

/// @title PositionManagerRebalancing
/// @author 3F Protocol
/// @notice Abstract contract handling rebalancing operations for PositionManager.
/// @dev Allows redistribution of collateral and debt across borrow positions.
abstract contract PositionManagerRebalancing is IPositionManagerRebalancing, PositionManagerBase {
  using SafeTransferLib for address;
  using LibExecutor for address;
  using LibView for PositionManagerStorageData;
  using EnumerableSetLib for EnumerableSetLib.AddressSet;

  /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
  /*                       REBALANCING                          */
  /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

  /// @inheritdoc IPositionManagerRebalancing
  /// @dev Reverts with {LibCommonErrors.Paused} if the contract is paused.
  ///      Reverts with {LibManagerErrors.RebalanceLossExceedsMax} if total assets decrease exceeds maxRebalanceLoss.
  ///      Protected by nonReentrant to prevent malicious modules from manipulating
  ///      guard state (pause/unpause) mid-transaction via callbacks.
  ///
  ///      Operator note: Morpho rounds repay shares down (toSharesDown) and borrow shares up
  ///      (toSharesUp), which can produce a 1-2 wei "phantom" NAV decrease across a single
  ///      rebalance even when no real economic loss occurs. With `maxRebalanceLoss == 0` the
  ///      check below would revert on this dust. Production deployments must therefore configure
  ///      `maxRebalanceLoss > 0` (a single basis point is enough); `maxRebalanceLoss == 0` will
  ///      revert otherwise-valid rebalances and must not be used.
  ///
  ///      An in-cap NAV loss during the rebalance (venue slippage, bridge fees, rounding)
  ///      re-anchors the performance reference at the post-loss state, so the levered slice of a
  ///      later recovery is charged as performance. Accepted policy: the loss is bounded by the
  ///      owner-set `maxRebalanceLoss`, the fee only mints on genuine upward movement from the
  ///      post-loss state, and rebalancing is role-gated.
  function rebalance(RebalancingData calldata data, address receiver)
    public
    virtual
    override
    onlyRoles(REBALANCER_ROLE)
    nonReentrant
    returns (uint256 collateralExcess, uint256 debtExcess)
  {
    PositionManagerStorageData storage _storage = LibStorage.positionManagerStorage();

    // Enforce cooldown between consecutive rebalance calls
    // (block-scoped so the temporaries do not deepen the stack for the rest of the function)
    {
      uint40 cooldown = _storage.rebalanceConfig.rebalanceCooldown;
      uint40 lastRebalance = _storage.rebalanceConfig.lastRebalanceTimestamp;
      if (cooldown > 0 && lastRebalance > 0) {
        // Safe: block.timestamp fits in uint40 for ~35,000 years
        // Subtraction is safe because block.timestamp >= lastRebalance (time is monotonic).
        // Using `elapsed < cooldown` instead of `timestamp < lastRebalance + cooldown`
        // to avoid uint40 overflow when cooldown is large.
        // forge-lint: disable-next-line(unsafe-typecast)
        if (uint40(block.timestamp) - lastRebalance < cooldown) {
          revert LibManagerErrors.RebalanceCooldownNotElapsed();
        }
      }
    }

    // Check if paused via transfer guard
    address guard = _storage.transferGuard;
    if (guard != address(0) && ITransferGuard(guard).paused(address(this))) {
      revert CommonErrors.Paused();
    }

    // Accrue fees based on pre-rebalance state and capture totalAssets/debt before operations
    (uint256 totalAssetsBefore, uint256 debtBefore) = _accrueFees();

    address _collateralAsset = _storage.metadata.collateralAsset;
    address _debtAsset = _storage.metadata.debtAsset;

    if (data.collateral > 0) {
      _collateralAsset.safeTransferFrom(msg.sender, address(this), data.collateral);
    }
    if (data.debt > 0) {
      _debtAsset.safeTransferFrom(msg.sender, address(this), data.debt);
    }

    uint256 opsLength = data.operations.length;
    for (uint256 i = 0; i < opsLength; ++i) {
      _dispatchRebalancingOperation(data.operations[i], _collateralAsset, _debtAsset);
    }

    // Rebase the performance reference to the post-rebalance state. A rebalance is a flow, not
    // a gain: the share supply is unchanged, so any carried pending basis is preserved as-is and
    // the rebalance neither crystallizes a performance fee nor writes off accrued debt carry.
    // Rebased (and the loss below checked) before the outgoing transfers so a receiver callback
    // cannot move module state into the new reference or donate to mask a loss; the transfers
    // change nothing either reads (module aggregates only). A donation during the callback
    // lands after the reference and is charged like any external repay.
    uint256 totalAssetsAfter = _rebaseReference(totalAssetsBefore, debtBefore, ERC20.totalSupply());

    // Check that totalAssets didn't decrease by more than maxRebalanceLoss
    if (totalAssetsAfter < totalAssetsBefore) {
      uint256 loss = totalAssetsBefore - totalAssetsAfter;
      // loss * BPS / totalAssetsBefore > maxRebalanceLoss
      // Rearranged to avoid division: loss * BPS > maxRebalanceLoss * totalAssetsBefore
      if (loss * BPS > uint256(_storage.rebalanceConfig.maxRebalanceLoss) * totalAssetsBefore) {
        revert LibManagerErrors.RebalanceLossExceedsMax();
      }
    }

    collateralExcess = _collateralAsset.safeTransferAll(receiver);
    debtExcess = _debtAsset.safeTransferAll(receiver);

    // Record rebalance timestamp for cooldown enforcement
    // Safe: block.timestamp fits in uint40 for ~35,000 years
    // forge-lint: disable-next-line(unsafe-typecast)
    _storage.rebalanceConfig.lastRebalanceTimestamp = uint40(block.timestamp);

    emit Rebalanced(receiver, data.collateral, data.debt, collateralExcess, debtExcess);
  }

  /// @dev Dispatches a single rebalancing operation to the appropriate helper.
  ///      Reverts with {LibManagerErrors.UnauthorizedPosition} if the position is not a registered borrow module.
  /// @param operation The rebalancing operation to execute
  /// @param _collateralAsset The collateral asset address
  /// @param _debtAsset The debt asset address
  function _dispatchRebalancingOperation(
    RebalancingOperation calldata operation,
    address _collateralAsset,
    address _debtAsset
  ) internal {
    address position = operation.position;
    uint256 amount = operation.amount;
    RebalancingOperationType operationType = operation.operationType;

    // Validate that the position is a registered borrow module
    if (!LibStorage.positionManagerStorage().borrowModules.contains(position)) {
      revert LibManagerErrors.UnauthorizedPosition();
    }

    if (operationType == RebalancingOperationType.REPAY) {
      position.repay(_debtAsset, amount);
    } else if (operationType == RebalancingOperationType.WITHDRAW) {
      position.withdraw(amount);
    } else if (operationType == RebalancingOperationType.BORROW) {
      position.borrow(amount);
    } else if (operationType == RebalancingOperationType.SUPPLY) {
      position.supply(_collateralAsset, amount);
    }
  }
}

